// RAG Explorer engine: a real retrieval pipeline over the portfolio's approved records, run in the
// browser. Ingestion → chunking → vectors → hybrid retrieval → context assembly → extractive,
// cited answer → evaluation. Honest labels: the vectors are TF-IDF (lexical), not neural embeddings,
// and the answer is extractive (quoted sentences), not generated by a language model.
import { knowledge, type KDoc } from '../agent/knowledge';
import { tokenize } from '../agent/search';

export type Chunk = { id: string; docId: string; title: string; url: string; text: string; tokens: string[] };

// ── 1. chunking: sentence windows with one sentence of overlap ───────
export const CHUNK_WORDS = 55;
const sentences = (t: string) => t.split(/(?<=[.!?])\s+(?=[A-Z0-9“"(])/).map((s) => s.trim()).filter(Boolean);

export function chunkDoc(d: KDoc, maxWords = CHUNK_WORDS): Chunk[] {
  const ss = sentences(d.text);
  const out: Chunk[] = [];
  let i = 0;
  while (i < ss.length) {
    const win: string[] = [];
    let words = 0, j = i;
    while (j < ss.length && (win.length === 0 || words + ss[j].split(/\s+/).length <= maxWords)) { win.push(ss[j]); words += ss[j].split(/\s+/).length; j++; }
    const text = win.join(' ');
    out.push({ id: `${d.id}~${out.length}`, docId: d.id, title: d.title, url: d.url, text, tokens: tokenize(`${text} ${out.length === 0 ? d.title : ''}`) });
    if (j >= ss.length) break;
    i = Math.max(i + 1, j - 1); // one sentence of overlap keeps a claim and its context together
  }
  return out;
}

// ── 2. index: TF-IDF vectors (L2-normalised) + BM25 statistics ───────
export type Index = { chunks: Chunk[]; df: Map<string, number>; idf: Map<string, number>; vecs: Map<string, number>[]; avgLen: number; docs: number };

export function buildIndex(docs: KDoc[] = knowledge()): Index {
  const chunks = docs.flatMap((d) => chunkDoc(d));
  const df = new Map<string, number>();
  for (const c of chunks) for (const t of new Set(c.tokens)) df.set(t, (df.get(t) ?? 0) + 1);
  const N = chunks.length;
  const idf = new Map([...df].map(([t, n]) => [t, Math.log(1 + (N - n + 0.5) / (n + 0.5))]));
  const vecs = chunks.map((c) => vectorize(c.tokens, idf));
  return { chunks, df, idf, vecs, avgLen: chunks.reduce((n, c) => n + c.tokens.length, 0) / Math.max(1, N), docs: docs.length };
}

export function vectorize(tokens: string[], idf: Map<string, number>): Map<string, number> {
  const tf = new Map<string, number>();
  for (const t of tokens) tf.set(t, (tf.get(t) ?? 0) + 1);
  const v = new Map<string, number>();
  for (const [t, n] of tf) { const w = (1 + Math.log(n)) * (idf.get(t) ?? 0); if (w > 0) v.set(t, w); }
  const norm = Math.sqrt([...v.values()].reduce((s, x) => s + x * x, 0)) || 1;
  for (const [t, w] of v) v.set(t, w / norm);
  return v;
}

export const cosine = (a: Map<string, number>, b: Map<string, number>) => { let s = 0; for (const [t, w] of a) s += w * (b.get(t) ?? 0); return s; };

function bm25(ix: Index, q: string[], i: number, k1 = 1.2, b = 0.75): number {
  const c = ix.chunks[i]; let s = 0;
  for (const t of new Set(q)) {
    const tf = c.tokens.filter((x) => x === t).length; if (!tf) continue;
    s += (ix.idf.get(t) ?? 0) * ((tf * (k1 + 1)) / (tf + k1 * (1 - b + (b * c.tokens.length) / ix.avgLen)));
  }
  return s;
}

// ── 3. retrieval: BM25 and cosine, fused by reciprocal rank ─────────
export type Hit = { chunk: Chunk; bm25: number; cosine: number; rankBm25: number; rankCos: number; rrf: number };

export function retrieve(ix: Index, query: string, k = 5): { q: string[]; hits: Hit[] } {
  const q = tokenize(query);
  if (!q.length) return { q, hits: [] };
  const qv = vectorize(q, ix.idf);
  const scored = ix.chunks.map((chunk, i) => ({ chunk, bm25: bm25(ix, q, i), cosine: cosine(qv, ix.vecs[i]) }));
  const byB = [...scored].sort((a, b) => b.bm25 - a.bm25);
  const byC = [...scored].sort((a, b) => b.cosine - a.cosine);
  const rb = new Map(byB.map((s, i) => [s.chunk.id, i + 1]));
  const rc = new Map(byC.map((s, i) => [s.chunk.id, i + 1]));
  const K = 60; // standard RRF constant
  const hits = scored
    .filter((s) => s.bm25 > 0 || s.cosine > 0)
    .map((s) => ({ ...s, rankBm25: rb.get(s.chunk.id)!, rankCos: rc.get(s.chunk.id)!, rrf: 1 / (K + rb.get(s.chunk.id)!) + 1 / (K + rc.get(s.chunk.id)!) }))
    .sort((a, b) => b.rrf - a.rrf);
  return { q, hits: hits.slice(0, k) };
}

// ── 4. context assembly under a token budget (≈ 4 characters per token) ─
export const estTokens = (s: string) => Math.ceil(s.length / 4);

export function assemble(hits: Hit[], budget = 400): { used: Hit[]; dropped: Hit[]; tokens: number } {
  const used: Hit[] = []; const dropped: Hit[] = []; let tokens = 0; const perDoc = new Map<string, number>();
  for (const h of hits) {
    const t = estTokens(h.chunk.text);
    if (tokens + t > budget || (perDoc.get(h.chunk.docId) ?? 0) >= 2) { dropped.push(h); continue; }
    used.push(h); tokens += t; perDoc.set(h.chunk.docId, (perDoc.get(h.chunk.docId) ?? 0) + 1);
  }
  return { used, dropped, tokens };
}

// ── 5. extractive, cited answer (no language model) ──────────────────
export type Cited = { text: string; source: number };
export type Answer = { sentences: Cited[]; sources: { n: number; title: string; url: string }[]; grounded: boolean };

export function answer(query: string, used: Hit[], maxSentences = 3): Answer {
  const q = new Set(tokenize(query));
  const sources = [...new Map(used.map((h) => [h.chunk.docId, h])).values()].map((h, i) => ({ n: i + 1, title: h.chunk.title, url: h.chunk.url, docId: h.chunk.docId }));
  // score: distinct query terms covered, mildly normalised by length; fragments under 6 words are skipped
  const cands = used.flatMap((h, rank) => sentences(h.chunk.text).filter((s) => s.split(/\s+/).length >= 6).map((s) => {
    const toks = tokenize(s); const hit = new Set(toks.filter((t) => q.has(t))).size;
    return { s, hit, src: sources.find((x) => x.docId === h.chunk.docId)!.n, score: (hit * 2) / Math.log(4 + toks.length) - rank * 0.05 };
  }));
  // relative threshold: keep sentences that cover at least 60% as many query terms as the best one
  const best = Math.max(0, ...cands.map((c) => c.hit));
  const strong = cands.filter((c) => c.hit > 0 && c.hit >= Math.ceil(best * 0.6));
  const seen = new Set<string>();
  const picked = strong.sort((a, b) => b.score - a.score).filter((c) => (seen.has(c.s) ? false : (seen.add(c.s), true))).slice(0, maxSentences);
  const out = picked.map((c) => ({ text: c.s, source: c.src }));
  // groundedness by construction: every sentence is verbatim text of a cited chunk
  const grounded = out.every((c) => used.some((h) => h.chunk.text.includes(c.text)));
  return { sentences: out, sources: sources.map(({ n, title, url }) => ({ n, title, url })), grounded };
}

// ── 6. evaluation: fixed questions with the source each should retrieve ─
export const EVAL_SET: { q: string; expect: string }[] = [
  { q: 'How does GMRE skip duplicate archives?', expect: 'project:gmre-log-parser' },
  { q: 'Which MFA method does SecureMed use?', expect: 'project:securemed' },
  { q: 'How were LIME and SHAP compared on FinBERT?', expect: 'project:finbert-xai' },
  { q: 'What happens when a boot image is tampered with?', expect: 'project:opticlab' },
  { q: 'How are Power BI KPIs refreshed?', expect: 'project:ticket-reporting-pipeline' },
  { q: 'How does the portfolio guide answer without an AI model?', expect: 'project:priyanshu-exe' },
  { q: 'How are shared test simulators allocated to automation agents?', expect: 'project:test-resource-scheduler' },
  { q: 'Which hardware cost project is planned?', expect: 'project:infrastructure-capacity' },
  { q: 'mutual TLS client certificate roles', expect: 'project:opticlab' },
  { q: 'Kubernetes network policies and restricted pods', expect: 'project:securemed' },
];

export type EvalRow = { q: string; expect: string; rank: number | null; top: string };
export function evaluate(ix: Index, k = 5): { rows: EvalRow[]; recallAt1: number; recallAtK: number; mrr: number } {
  const rows = EVAL_SET.map(({ q, expect }) => {
    const { hits } = retrieve(ix, q, k);
    const rank = hits.findIndex((h) => h.chunk.docId.split('#')[0] === expect) + 1 || null;
    return { q, expect, rank, top: hits[0]?.chunk.docId ?? '—' };
  });
  const n = rows.length;
  return {
    rows,
    recallAt1: rows.filter((r) => r.rank === 1).length / n,
    recallAtK: rows.filter((r) => r.rank !== null).length / n,
    mrr: rows.reduce((s, r) => s + (r.rank ? 1 / r.rank : 0), 0) / n,
  };
}
